#define MAX_STEPS 400
#define MAX_DIST 100.
#define SURF_DIST .001

mat2 Rot(float a) {
    float s=sin(a), c=cos(a);
    return mat2(c, -s, s, c);
}

#define FK(k) floatBitsToInt(k*k/7.)^floatBitsToInt(k)
float hash(float a, float b) {
    int x = FK(a), y = FK(b);
    return float((x*x+y)*(y*y-x)-x)/2.14e9;
}

vec3 erot(vec3 p, vec3 ax, float ro) {
  return mix(dot(ax, p)*ax, p, cos(ro)) + cross(ax,p)*sin(ro);
}

vec3 face(vec3 p) {
     vec3 a = abs(p);
     return step(a.yzx, a.xyz)*step(a.zxy, a.xyz)*sign(p);
}

float sdBox(vec3 p, vec3 s) {
    p = abs(p)-s;
	return length(max(p, 0.))+min(max(p.x, max(p.y, p.z)), 0.);
}

vec3 getRo() {
    vec2 m = iMouse.xy/iResolution.xy;

    vec3 ro = (0.51 + 0.5 * thc(6., 0.2 * iTime)) * 1.8 * vec3(0, 1, -1);


    float t = 0.2 * iTime;
    float o = 2. * pi / 3.;

    //vec3 ro = 0.1 * vec3(cos(t-o), cos(t), cos(t+o)); //2.6
  //  ro = vec3(0,4.4,1.);
   ro.yz *= Rot(-m.y*3.14+1.);
    ro.xz *= Rot(-m.x*6.2831);
    return ro;
}

vec3 getRa() {
   return vec3(0);
    return vec3(0, 1, 0);
}

vec2 op1(vec2 p, float m) {
    p *= 1. + 0.125 * m;
    //p *= Rot(0. * length(p) + 0. * iTime);
    return abs(p) - m;
}

float op2(float l, vec2 p, float r) {

    return min(l + 0.125 * (abs(p.x) + abs(p.y)), length(p) - 0.75 * r);

    //return (0.5 + 0.5 * cos(pi * l - iTime)) * min(l, length(p) - r);
}

vec2 op3(vec2 p, float a) {
    return p * Rot(a);
}

float GetDist(vec3 p) {

    float r1 = 0.;
    float r2 = 0.1;

    vec2 xy = p.xy, yz = p.yz, zx = p.zx;
    float m = sqrt(2.) / 2.;
    float dxy = length(xy) - m, dyz = length(yz) - m, dzx = length(zx) - m;
    for (float i = 0.; i < 6.; i++) {  
        float io = 2. * pi * i / 6.;
        //m *= 0.5 + 0.5 * cos(iTime);
        xy = op1(xy, m), yz = op1(yz, m), zx = op1(zx, m);    
        m *= 0.45 + 0.05 * cos(8. * mlength(p) + io + iTime);
        float r = m;
        dxy = op2(dxy, xy, r), dyz = op2(dyz, yz, r), dzx = op2(dzx, zx, r);
    }

    float d = min(min(dxy, dyz), dzx);

    float d2 = length(p) - 1.48;
    d2 = -min(d, -d2);


    //d = max(d - r2, length(p) - 1. + 0.5 * cos(2. * length(p) + iTime));
   // d = min(d, d2);

    return d2;
}

float RayMarch(vec3 ro, vec3 rd, float z) {

    float dO=0.;

    for(int i=0; i<MAX_STEPS; i++) {
    	vec3 p = ro + rd*dO;
        float dS = GetDist(p);
        if(abs(dS)<SURF_DIST || dO>MAX_DIST) break;
        dO += dS*z; 
    }

    return min(dO, MAX_DIST);
}

vec3 GetNormal(vec3 p) {
	float d = GetDist(p);
    vec2 e = vec2(.001, 0);

    vec3 n = d - vec3(
        GetDist(p-e.xyy),
        GetDist(p-e.yxy),
        GetDist(p-e.yyx));

    return normalize(n);
}

vec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = f*z,
        i = c + uv.x*r + uv.y*u,
        d = normalize(i);
    return d;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    vec3 ro = getRo();
    vec3 ra = getRa();

    vec3 rd = GetRayDir(uv, ro, ra, 1.4);
    vec3 col = vec3(0);

    float d = RayMarch(ro, rd, 1.);

    float IOR = 1.05;
    if(d<MAX_DIST) {
        vec3 p = ro + rd * d;
        vec3 n = GetNormal(p);
        vec3 r = reflect(rd, n);

        vec3 pIn = p - 4. * SURF_DIST * n;
        vec3 rdIn = refract(rd, n, 1./IOR);
        float dIn = RayMarch(pIn, rdIn, -1.);

        vec3 pExit = pIn + dIn * rdIn;
        vec3 nExit = -GetNormal(pExit); // *-1.; ?

        float dif = dot(n, normalize(vec3(1,2,3)))*.5+.5;
        col = vec3(1.);

        float fresnel = pow(1.+dot(rdIn, nExit), 5.);
        //col += fresnel;
        float fresnel2 = pow(1.+dot(rd, n), 1.5); 
        col *= fresnel2;

        //col *= 0.5 + 0.5 * n;

        col = clamp(col, 0., 1.);
        vec3 e = vec3(1);
        col *= pal(n.y, e, e, e, 0.35 * vec3(0,1,2)/3.);
        col += 0.15 * n.y;
    }

    col = pow(col, vec3(.4545));	// gamma correction

    fragColor = vec4(col,1.0);
}

